add_cart_item.code:
use WebCommander\Sdk\Resources\Carts\Carts;

$response = Carts::addCartItem($client, [
    'product_id' => 101, 'quantity' => 1, 'customer_id' => 45, 'session_id' => 'cart-7f3a9c2e1b',
    'shipping_address' => [
        'first_name' => 'Alex', 'last_name' => 'Taylor', 'address_line1' => '1 Example Street', 'address_line2' => '',
        'city' => 'Sydney', 'post_code' => '2000', 'phone' => '', 'mobile' => '', 'fax' => '',
        'email' => 'alex.taylor@example.com', 'country_code' => 'AU', 'state_code' => 'NSW',
    ],
]);

echo $response->map['cart']['session_id'], ' ', $response->map['cart']['items'][0]['id'], PHP_EOL;

get_cart.code:
use WebCommander\Sdk\Resources\Carts\Carts;

$response = Carts::getCart($client, 'cart-7f3a9c2e1b');

$cart = $response->map['cart'];
foreach ($cart['items'] as $item) {
    echo $item['id'], ' ', $item['product']['sku'], ' x', $item['quantity'], ': ', $item['pricing']['total'], PHP_EOL;
}
echo 'Shipping tax: ', $cart['shipping']['shipping_tax'], PHP_EOL;
echo 'Grand total: ', $cart['totals']['grand_total'], PHP_EOL;

update_cart_item.code:
use WebCommander\Sdk\Resources\Carts\Carts;

$response = Carts::updateCartItem($client, 'cart-7f3a9c2e1b', ['cart_item_id' => 42, 'quantity' => 2]);

$cart = $response->map['cart'];
foreach ($cart['items'] as $item) {
    echo $item['id'], ' x', $item['quantity'], ': ', $item['pricing']['total'], PHP_EOL;
}
echo 'Subtotal: ', $cart['totals']['subtotal'], PHP_EOL;

create_order_from_cart.code:
use WebCommander\Sdk\Resources\Carts\Carts;

$response = Carts::createOrderFromCart($client, 'cart-7f3a9c2e1b', [
    'customer_id' => 123,
    'payment_gateway' => 'PIS',
    'delivery_type' => 'shipping',
    'transaction_no' => 'web-order-0001',
]);

$order = $response->map['order'];
echo $response->map['status'], ' ', $order['order_id'], ' ', $order['order_status'], ' ', $order['payment_status'], PHP_EOL;
echo 'Due: ', $order['due'], PHP_EOL;
